import { Decimal } from './decimal.ts';

export const ZERO: Decimal = Decimal.of(0);
export const ZERO_MONEY: Decimal = Decimal.of('0.00');
export const HUNDRED: Decimal = Decimal.of(100);

/**
 * Porcentaje de un importe, redondeado de inmediato a 2 decimales (mitad hacia arriba).
 * @rule R-025
 */
export function percentOf(amount: Decimal, percentage: Decimal): Decimal {
  return amount.times(percentage).dividedBy(HUNDRED, 2, 'HALF_UP');
}

/**
 * Complemento de un porcentaje (100 - pct).
 * @rule R-025
 */
export function complementOfPercent(percentage: Decimal): Decimal {
  return HUNDRED.minus(percentage);
}

/**
 * Ajusta un importe a la precisión NUMBER(14,2) con ROUND.
 * @rule R-025
 */
export function toMoney(value: Decimal): Decimal {
  return value.setScale(2, 'HALF_UP');
}

const MONTH_LENGTHS: readonly number[] = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
const DATE_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

function daysInMonth(year: number, month: number): number {
  return month === 2 && isLeapYear(year) ? 29 : MONTH_LENGTHS[month - 1];
}

function daysFromCivil(year: number, month: number, day: number): number {
  const y = month <= 2 ? year - 1 : year;
  const era = Math.floor(y / 400);
  const yearOfEra = y - era * 400;
  const shiftedMonth = month > 2 ? month - 3 : month + 9;
  const dayOfYear = Math.floor((153 * shiftedMonth + 2) / 5) + day - 1;
  const dayOfEra =
    yearOfEra * 365 + Math.floor(yearOfEra / 4) - Math.floor(yearOfEra / 100) + dayOfYear;
  return era * 146097 + dayOfEra - 719468;
}

/** Fecha civil sin hora (equivale a TRUNC(fecha)); los plazos se cuentan en días calendario. */
export class CalendarDate {
  readonly epochDay: number;
  readonly iso: string;

  private constructor(epochDay: number, iso: string) {
    this.epochDay = epochDay;
    this.iso = iso;
  }

  static parse(text: string): CalendarDate | null {
    const match = DATE_PATTERN.exec(text.trim());
    if (match === null) {
      return null;
    }
    const year = parseInt(match[1], 10);
    const month = parseInt(match[2], 10);
    const day = parseInt(match[3], 10);
    if (month < 1 || month > 12 || day < 1 || day > daysInMonth(year, month)) {
      return null;
    }
    return new CalendarDate(daysFromCivil(year, month, day), text.trim());
  }

  static epoch(): CalendarDate {
    return new CalendarDate(0, '1970-01-01');
  }

  /** Días transcurridos desde `other` hasta esta fecha (negativo si es anterior). */
  daysSince(other: CalendarDate): number {
    return this.epochDay - other.epochDay;
  }

  isBefore(other: CalendarDate): boolean {
    return this.epochDay < other.epochDay;
  }

  isAfter(other: CalendarDate): boolean {
    return this.epochDay > other.epochDay;
  }
}

export type RejectionReason =
  | 'POLIZA_NO_VIGENTE'
  | 'FUERA_DE_VIGENCIA'
  | 'DENUNCIA_EXTEMPORANEA'
  | 'COBERTURA_NO_CONTRATADA'
  | 'EN_PERIODO_CARENCIA'
  | 'PRIMA_EN_MORA'
  | 'BAJO_DEDUCIBLE'
  | 'SUMA_ASEGURADA_AGOTADA';

export type ApprovalReason = 'SOSPECHA_FRAUDE' | 'SUPERA_TOPE_AUTOMATICO' | 'LIQUIDACION_AUTOMATICA';

export type ErrorCode = 'ORA-20001' | 'ORA-20010' | 'ENTRADA_INVALIDA';

export type SettlementStatus = 'APROBADA' | 'RECHAZADA' | 'PENDIENTE_APROBACION' | 'ERROR';

export type ApprovalStatus = 'APROBADA' | 'PENDIENTE_APROBACION';

export type ClaimState = 'REGISTRADO' | 'LIQUIDADO' | 'RECHAZADO' | 'PENDIENTE_REVISION';

const MAX_LENGTH = 400;

/** Marcas de observación inmutables. */
export class Observations {
  readonly marks: readonly string[];

  private constructor(marks: readonly string[]) {
    this.marks = marks;
  }

  static empty(): Observations {
    return new Observations([]);
  }

  /**
   * Agrega una marca respetando el orden de aplicación.
   * @rule R-022
   */
  add(mark: string): Observations {
    return new Observations([...this.marks, mark]);
  }

  /**
   * Texto con marcas separadas por ';' (vacío si no hay ajustes), máximo 400 caracteres.
   * @rule R-022
   */
  toText(): string {
    return this.marks.join(';').slice(0, MAX_LENGTH);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Observations } from './Observations.ts';

/** Importe resultante de un ajuste junto con las observaciones acumuladas. */
export interface Adjusted {
  readonly amount: Decimal;
  readonly observations: Observations;
}

import type { Decimal } from '../shared/decimal.ts';
import type { CalendarDate } from './CalendarDate.ts';

/** Datos de entrada de la liquidación, ya tipados. */
export interface SettlementRequest {
  readonly claimId: string | null;
  readonly claimStatus: string | null;
  readonly claimedAmount: Decimal;
  readonly occurrenceDate: CalendarDate;
  readonly reportDate: CalendarDate;
  readonly processDate: CalendarDate;
  readonly policyStatus: string;
  readonly policyStartDate: CalendarDate;
  readonly policyEndDate: CalendarDate;
  readonly lineOfBusiness: string;
  readonly sumInsured: Decimal;
  readonly deductibleType: string;
  readonly deductibleValue: Decimal;
  readonly pendingPremium: Decimal;
  readonly customerCategory: string;
  readonly coverageFound: boolean;
  readonly coverageLimit: Decimal;
  readonly coveragePct: Decimal;
  readonly waitingDays: number;
  readonly priorLiquidatedClaims365d: number;
  readonly totalIndemnified: Decimal;
}

import { Decimal } from '../shared/decimal.ts';

export type ParameterName =
  | 'DIAS_MAX_DENUNCIA'
  | 'DIAS_MAX_DENUNCIA_VIDA'
  | 'TOLERANCIA_MORA_VIP'
  | 'DEDUCIBLE_MINIMO'
  | 'PCT_DESCUENTO_DED_VIP'
  | 'MAX_SINIESTROS_ANUAL'
  | 'PCT_PENALIZACION_SINIEST'
  | 'UMBRAL_RETENCION'
  | 'TASA_RETENCION'
  | 'DIAS_ALERTA_FRAUDE'
  | 'PCT_ALERTA_FRAUDE'
  | 'TOPE_AUTO_APROBACION'
  | 'FACTOR_INFLACION';

const REQUIRED_PARAMETERS: readonly ParameterName[] = [
  'DIAS_MAX_DENUNCIA',
  'DIAS_MAX_DENUNCIA_VIDA',
  'TOLERANCIA_MORA_VIP',
  'DEDUCIBLE_MINIMO',
  'PCT_DESCUENTO_DED_VIP',
  'MAX_SINIESTROS_ANUAL',
  'PCT_PENALIZACION_SINIEST',
  'UMBRAL_RETENCION',
  'TASA_RETENCION',
  'DIAS_ALERTA_FRAUDE',
  'PCT_ALERTA_FRAUDE',
  'TOPE_AUTO_APROBACION',
  'FACTOR_INFLACION',
];

const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;

export type ParameterLoadResult =
  | { readonly ok: true; readonly parameters: BusinessParameters }
  | { readonly ok: false; readonly missing: string };

/** Parámetros de negocio, todos obligatorios. */
export class BusinessParameters {
  private readonly values: ReadonlyMap<ParameterName, Decimal>;

  private constructor(values: ReadonlyMap<ParameterName, Decimal>) {
    this.values = values;
  }

  /**
   * Carga todos los parámetros; informa el primero que falta (incluido FACTOR_INFLACION).
   * @rule R-024
   */
  static fromRaw(raw: ReadonlyMap<string, string>): ParameterLoadResult {
    const values = new Map<ParameterName, Decimal>();
    for (const name of REQUIRED_PARAMETERS) {
      const text = raw.get(name);
      if (text === undefined || !DECIMAL_PATTERN.test(text)) {
        return { ok: false, missing: name };
      }
      values.set(name, Decimal.of(text));
    }
    return { ok: true, parameters: new BusinessParameters(values) };
  }

  /**
   * Valor de un parámetro (siempre presente tras la carga validada).
   * @rule R-024
   */
  get(name: ParameterName): Decimal {
    return this.values.get(name) as Decimal;
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { ZERO_MONEY } from '../shared/rounding.ts';

/** Importes de la liquidación, todos con escala 2. */
export class SettlementAmounts {
  readonly base: Decimal;
  readonly deductible: Decimal;
  readonly covered: Decimal;
  readonly withholding: Decimal;
  readonly net: Decimal;

  private constructor(
    base: Decimal,
    deductible: Decimal,
    covered: Decimal,
    withholding: Decimal,
    net: Decimal,
  ) {
    this.base = base;
    this.deductible = deductible;
    this.covered = covered;
    this.withholding = withholding;
    this.net = net;
  }

  /**
   * Importes de un rechazo: todos en 0.
   * @rule R-008
   */
  static zero(): SettlementAmounts {
    return new SettlementAmounts(ZERO_MONEY, ZERO_MONEY, ZERO_MONEY, ZERO_MONEY, ZERO_MONEY);
  }

  /**
   * Compone los importes; neto = cubierto - retención.
   * @rule R-018
   */
  static of(
    base: Decimal,
    deductible: Decimal,
    covered: Decimal,
    withholding: Decimal,
  ): SettlementAmounts {
    return new SettlementAmounts(base, deductible, covered, withholding, covered.minus(withholding));
  }
}

import { SettlementAmounts } from './SettlementAmounts.ts';
import type { Observations } from './Observations.ts';
import type {
  ApprovalReason,
  ApprovalStatus,
  ErrorCode,
  RejectionReason,
  SettlementStatus,
} from './ReasonCode.ts';

/** Resultado de una liquidación (los errores de negocio no son excepciones). */
export class SettlementResult {
  readonly status: SettlementStatus;
  readonly reasonCode: string;
  readonly amounts: SettlementAmounts;
  readonly observations: string;

  private constructor(
    status: SettlementStatus,
    reasonCode: string,
    amounts: SettlementAmounts,
    observations: string,
  ) {
    this.status = status;
    this.reasonCode = reasonCode;
    this.amounts = amounts;
    this.observations = observations;
  }

  /**
   * Rechazo: importes en 0 y observaciones acumuladas hasta ese punto.
   * @rule R-008
   */
  static rejected(reason: RejectionReason, observations: Observations): SettlementResult {
    return new SettlementResult('RECHAZADA', reason, SettlementAmounts.zero(), observations.toText());
  }

  static decided(
    status: ApprovalStatus,
    reason: ApprovalReason,
    amounts: SettlementAmounts,
    observations: Observations,
  ): SettlementResult {
    return new SettlementResult(status, reason, amounts, observations.toText());
  }

  /** Error de negocio con código (ORA-xxxx); el mensaje viaja en observations. */
  static failed(code: ErrorCode, message: string): SettlementResult {
    return new SettlementResult('ERROR', code, SettlementAmounts.zero(), message);
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';

/** Validación de procedencia: devuelve el motivo de rechazo o null si continúa. */
export interface EligibilityRule {
  evaluate(request: SettlementRequest, parameters: BusinessParameters): RejectionReason | null;
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { EligibilityRule } from './EligibilityRule.ts';

export class PolicyInForceRule implements EligibilityRule {
  /**
   * Solo se indemnizan pólizas VIGENTE.
   * @rule R-002
   */
  evaluate(request: SettlementRequest, _parameters: BusinessParameters): RejectionReason | null {
    return request.policyStatus !== 'VIGENTE' ? 'POLIZA_NO_VIGENTE' : null;
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { EligibilityRule } from './EligibilityRule.ts';

export class OccurrenceWithinValidityRule implements EligibilityRule {
  /**
   * La ocurrencia debe estar dentro de la vigencia, con inicio y fin inclusivos.
   * @rule R-003
   */
  evaluate(request: SettlementRequest, _parameters: BusinessParameters): RejectionReason | null {
    const before = request.occurrenceDate.isBefore(request.policyStartDate);
    const after = request.occurrenceDate.isAfter(request.policyEndDate);
    return before || after ? 'FUERA_DE_VIGENCIA' : null;
  }
}

import { Decimal } from '../shared/decimal.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { EligibilityRule } from './EligibilityRule.ts';

export class ReportingDeadlineRule implements EligibilityRule {
  /**
   * Plazo máximo de denuncia: 365 días para VIDA y 30 para el resto; el último día se acepta.
   * @rule R-004
   */
  evaluate(request: SettlementRequest, parameters: BusinessParameters): RejectionReason | null {
    const deadline =
      request.lineOfBusiness === 'VIDA'
        ? parameters.get('DIAS_MAX_DENUNCIA_VIDA')
        : parameters.get('DIAS_MAX_DENUNCIA');
    const reportDays = request.reportDate.daysSince(request.occurrenceDate);
    return Decimal.of(reportDays).gt(deadline) ? 'DENUNCIA_EXTEMPORANEA' : null;
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { EligibilityRule } from './EligibilityRule.ts';

export class CoverageContractedRule implements EligibilityRule {
  /**
   * La cobertura reclamada debe estar contratada en la póliza.
   * @rule R-005
   */
  evaluate(request: SettlementRequest, _parameters: BusinessParameters): RejectionReason | null {
    return request.coverageFound ? null : 'COBERTURA_NO_CONTRATADA';
  }
}

import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { RejectionReason } from '../model/ReasonCode.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { EligibilityRule } from './EligibilityRule.ts';

export class WaitingPeriodRule implements EligibilityRule {
  /**
   * Periodo de carencia: días desde el inicio de la póliza < días de carencia implica rechazo.
   * @rule R-006
   */
  evaluate(request: SettlementRequest, _parameters: BusinessParameters): RejectionReason | null {
    const daysSinceStart = request.occurrenceDate.daysSince(request.policyStartDate);
    return daysSinceStart < request.waitingDays ? 'EN_PERIODO_CARENCIA' : null;
  }
}

import { ZERO } from '../shared/rounding.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';

export type ArrearsAssessment = 'CLEAR' | 'TOLERATED_VIP' | 'IN_ARREARS';

export class PremiumArrearsPolicy {
  /**
   * Prima pendiente > 0 rechaza por PRIMA_EN_MORA, salvo VIP con deuda <= tolerancia.
   * @rule R-007
   */
  assess(request: SettlementRequest, parameters: BusinessParameters): ArrearsAssessment {
    if (!request.pendingPremium.gt(ZERO)) {
      return 'CLEAR';
    }
    return this.isVipTolerated(request, parameters) ? 'TOLERATED_VIP' : 'IN_ARREARS';
  }

  /** @rule R-007 */
  private isVipTolerated(request: SettlementRequest, parameters: BusinessParameters): boolean {
    return (
      request.customerCategory === 'VIP' &&
      request.pendingPremium.lte(parameters.get('TOLERANCIA_MORA_VIP'))
    );
  }
}

export class ClaimStateSpecification {
  /**
   * Solo se liquidan siniestros en estado REGISTRADO.
   * @rule R-001
   */
  isSettleable(claimStatus: string): boolean {
    return claimStatus === 'REGISTRADO';
  }
}

import type { Adjusted } from '../model/Adjusted.ts';
import type { Observations } from '../model/Observations.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';

export class CoverageLimitCap {
  /**
   * Monto base = menor entre lo reclamado y el límite; marca LIMITE_COBERTURA si se topa.
   * @rule R-009
   */
  apply(request: SettlementRequest, observations: Observations): Adjusted {
    if (request.claimedAmount.gt(request.coverageLimit)) {
      return { amount: request.coverageLimit, observations: observations.add('LIMITE_COBERTURA') };
    }
    return { amount: request.claimedAmount, observations };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';

/** Estrategia de cálculo del deducible según su tipo. */
export interface DeductibleStrategy {
  calculate(
    base: Decimal,
    value: Decimal,
    parameters: BusinessParameters,
    observations: Observations,
  ): Adjusted;
}

import type { Decimal } from '../shared/decimal.ts';
import { toMoney } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';

export class FixedDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible FIJO: se toma el valor de la póliza, sin mínimo.
   * @rule R-010
   */
  calculate(
    _base: Decimal,
    value: Decimal,
    _parameters: BusinessParameters,
    observations: Observations,
  ): Adjusted {
    return { amount: toMoney(value), observations };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { percentOf, toMoney } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';

export class PercentageDeductibleStrategy implements DeductibleStrategy {
  /**
   * Deducible PORCENTAJE sobre el monto base con mínimo; marca DEDUCIBLE_MINIMO.
   * @rule R-011
   * @rule R-025
   */
  calculate(
    base: Decimal,
    value: Decimal,
    parameters: BusinessParameters,
    observations: Observations,
  ): Adjusted {
    const computed = percentOf(base, value);
    const minimum = toMoney(parameters.get('DEDUCIBLE_MINIMO'));
    if (computed.lt(minimum)) {
      return { amount: minimum, observations: observations.add('DEDUCIBLE_MINIMO') };
    }
    return { amount: computed, observations };
  }
}

import { complementOfPercent, percentOf, ZERO } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';

export class VipDeductibleDiscount {
  /**
   * Descuento VIP sobre el deducible > 0, aplicado después del mínimo; marca DESCUENTO_VIP.
   * @rule R-012
   */
  apply(deductible: Adjusted, customerCategory: string, parameters: BusinessParameters): Adjusted {
    if (customerCategory !== 'VIP' || !deductible.amount.gt(ZERO)) {
      return deductible;
    }
    const factor = complementOfPercent(parameters.get('PCT_DESCUENTO_DED_VIP'));
    return {
      amount: percentOf(deductible.amount, factor),
      observations: deductible.observations.add('DESCUENTO_VIP'),
    };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';
import type { DeductibleStrategy } from './DeductibleStrategy.ts';
import type { VipDeductibleDiscount } from './VipDeductibleDiscount.ts';

export class DeductibleCalculator {
  private readonly fixed: DeductibleStrategy;
  private readonly percentage: DeductibleStrategy;
  private readonly vipDiscount: VipDeductibleDiscount;

  constructor(
    fixed: DeductibleStrategy,
    percentage: DeductibleStrategy,
    vipDiscount: VipDeductibleDiscount,
  ) {
    this.fixed = fixed;
    this.percentage = percentage;
    this.vipDiscount = vipDiscount;
  }

  /**
   * Selecciona FIJO (R-010) o cualquier otro tipo como PORCENTAJE (R-011) y aplica el descuento VIP (R-012).
   * @rule R-010
   * @rule R-011
   * @rule R-012
   */
  compute(
    request: SettlementRequest,
    parameters: BusinessParameters,
    base: Decimal,
    observations: Observations,
  ): Adjusted {
    const strategy = request.deductibleType === 'FIJO' ? this.fixed : this.percentage;
    const raw = strategy.calculate(base, request.deductibleValue, parameters, observations);
    return this.vipDiscount.apply(raw, request.customerCategory, parameters);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { percentOf } from '../shared/rounding.ts';

export class CoveredAmountCalculator {
  /**
   * Cubierto = ROUND((base - deducible) * % cobertura / 100, 2).
   * @rule R-013
   * @rule R-025
   */
  calculate(base: Decimal, deductible: Decimal, coveragePct: Decimal): Decimal {
    return percentOf(base.minus(deductible), coveragePct);
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { ZERO } from '../shared/rounding.ts';

export class LowDeductibleSpecification {
  /**
   * Cubierto <= 0 implica rechazo por BAJO_DEDUCIBLE.
   * @rule R-014
   */
  isSatisfiedBy(covered: Decimal): boolean {
    return covered.lte(ZERO);
  }
}

import { Decimal } from '../shared/decimal.ts';
import { complementOfPercent, percentOf } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { BusinessParameters } from '../model/BusinessParameters.ts';
import type { Observations } from '../model/Observations.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';

export class ClaimsFrequencyPenalty {
  /**
   * Con 3 o más siniestros liquidados en los 365 días previos, el cubierto baja 10 % y se marca PENALIZACION_SINIESTRALIDAD.
   * @rule R-015
   */
  apply(
    covered: Decimal,
    request: SettlementRequest,
    parameters: BusinessParameters,
    observations: Observations,
  ): Adjusted {
    const priorClaims = Decimal.of(request.priorLiquidatedClaims365d);
    if (priorClaims.lt(parameters.get('MAX_SINIESTROS_ANUAL'))) {
      return { amount: covered, observations };
    }
    const factor = complementOfPercent(parameters.get('PCT_PENALIZACION_SINIEST'));
    return {
      amount: percentOf(covered, factor),
      observations: observations.add('PENALIZACION_SINIESTRALIDAD'),
    };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { ZERO } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
import type { Observations } from '../model/Observations.ts';
import type { SettlementRequest } from '../model/SettlementRequest.ts';

export class SumInsuredCap {
  /**
   * Suma remanente = suma asegurada - total indemnizado.
   * @rule R-016
   */
  remaining(request: SettlementRequest): Decimal {
    return request.sumInsured.minus(request.totalIndemnified);
  }

  /**
   * Remanente <= 0 implica rechazo por SUMA_ASEGURADA_AGOTADA.
   * @rule R-016
   */
  isExhausted(request: SettlementRequest): boolean {
    return this.remaining(request).lte(ZERO);
  }

  /**
   * Si el cubierto supera el remanente, se limita a él y se marca TOPE_SUMA_ASEGURADA.
   * @rule R-016
   */
  apply(covered: Decimal, request: SettlementRequest, observations: Observations): Adjusted {
    const remaining = this.remaining(request);
    if (covered.gt(remaining)) {
      return { amount: remaining, observations: observations.add('TOPE_SUMA_ASEGURADA') };
    }
    return { amount: covered, observations };
  }
}

import type { Decimal } from '../shared/decimal.ts';
import { percentOf, ZERO_MONEY } from '../shared/rounding.ts';
import type { Adjusted } from '../model/Adjusted.ts';
