export class WithholdingPolicy {
  /**
   * Retención del 2 % si el ramo no es VIDA y el cubierto supera el umbral (estrictamente mayor); marca RETENCION_APLICADA.
   * @rule R-017
   */
  apply(
    covered: Decimal,
    request: SettlementRequest,
    parameters: BusinessParameters,
    observations: Observations,
  ): Adjusted {
    const applies =
      request.lineOfBusiness !== 'VIDA' && covered.gt(parameters.get('UMBRAL_RETENCION'));
    if (!applies) {
      return { amount: ZERO_MONEY, observations };
    }
    return {
      amount: percentOf(covered, parameters.get('TASA_RETENCION')),
      observations: observations.add('RETENCION_APLICADA'),
    };
  }
}

