export class FraudAlertSpecification {
  /**
   * Sospecha de fraude: ocurrencia en los primeros 15 días (inclusive) y reclamado >= 80 % del límite.
   * @rule R-019
   */
  isSatisfiedBy(request: SettlementRequest, parameters: BusinessParameters): boolean {
    return this.isWithinEarlyWindow(request, parameters) && this.isHighClaim(request, parameters);
  }

  /** @rule R-019 */
  private isWithinEarlyWindow(request: SettlementRequest, parameters: BusinessParameters): boolean {
    const daysSinceStart = request.occurrenceDate.daysSince(request.policyStartDate);
    return Decimal.of(daysSinceStart).lte(parameters.get('DIAS_ALERTA_FRAUDE'));
  }

  /** @rule R-019 */
  private isHighClaim(request: SettlementRequest, parameters: BusinessParameters): boolean {
    const threshold = percentOf(request.coverageLimit, parameters.get('PCT_ALERTA_FRAUDE'));
    return request.claimedAmount.gte(threshold);
  }
}

