export interface ApprovalDecision {
  readonly status: ApprovalStatus;
  readonly reason: ApprovalReason;
}

export class ApprovalDecisionPolicy {
  private readonly fraudAlert: FraudAlertSpecification;

  constructor(fraudAlert: FraudAlertSpecification) {
    this.fraudAlert = fraudAlert;
  }

  /**
   * El fraude tiene prioridad (R-019); si no, neto > tope automático queda pendiente (R-020); si no, se aprueba.
   * @rule R-019
   * @rule R-020
   */
  decide(request: SettlementRequest, parameters: BusinessParameters, net: Decimal): ApprovalDecision {
    if (this.fraudAlert.isSatisfiedBy(request, parameters)) {
      return { status: 'PENDIENTE_APROBACION', reason: 'SOSPECHA_FRAUDE' };
    }
    if (net.gt(parameters.get('TOPE_AUTO_APROBACION'))) {
      return { status: 'PENDIENTE_APROBACION', reason: 'SUPERA_TOPE_AUTOMATICO' };
    }
    return { status: 'APROBADA', reason: 'LIQUIDACION_AUTOMATICA' };
  }
}

import type { ClaimState, SettlementStatus } from '../model/ReasonCode.ts';

export class ClaimStateTransition {
  /**
   * Nuevo estado del siniestro según el resultado de la liquidación; null si no hubo liquidación.
   * @rule R-021
   */
  next(status: SettlementStatus): ClaimState | null {
    switch (status) {
      case 'APROBADA':
        return 'LIQUIDADO';
      case 'RECHAZADA':
        return 'RECHAZADO';
      case 'PENDIENTE_APROBACION':
        return 'PENDIENTE_REVISION';
      default:
        return null;
    }
  }
}

import type { CalendarDate } from '../model/CalendarDate.ts';

export class ClaimSelectionSpecification {
  /**
   * Un siniestro entra al lote si está REGISTRADO y su denuncia es <= fecha de proceso. Orden de proceso: id ascendente.
   * @rule R-023
   */
  isSatisfiedBy(claimStatus: string, reportDate: CalendarDate, processDate: CalendarDate): boolean {
    return claimStatus === 'REGISTRADO' && !reportDate.isAfter(processDate);
  }
}

