interface Screening {
  readonly reason: RejectionReason | null;
  readonly observations: Observations;
}

export interface SettlementPolicies {
  readonly eligibilityRules: readonly EligibilityRule[];
  readonly arrears: PremiumArrearsPolicy;
  readonly limitCap: CoverageLimitCap;
  readonly deductible: DeductibleCalculator;
  readonly coveredCalculator: CoveredAmountCalculator;
  readonly lowDeductible: LowDeductibleSpecification;
  readonly penalty: ClaimsFrequencyPenalty;
  readonly sumCap: SumInsuredCap;
  readonly withholding: WithholdingPolicy;
  readonly approval: ApprovalDecisionPolicy;
}

/** Servicio de dominio que orquesta las reglas de liquidación en el orden fijado por R-008. */
export class ClaimSettlementService {
  private readonly policies: SettlementPolicies;

  constructor(policies: SettlementPolicies) {
    this.policies = policies;
  }

  /**
   * Orden: póliza vigente, vigencia, denuncia, cobertura, carencia, morosidad, bajo deducible, suma agotada. La primera que falla decide el motivo.
   * @rule R-008
   */
  settle(request: SettlementRequest, parameters: BusinessParameters): SettlementResult {
    const screening = this.screen(request, parameters);
    if (screening.reason !== null) {
      return SettlementResult.rejected(screening.reason, screening.observations);
    }
    return this.liquidate(request, parameters, screening.observations);
  }

  /** @rule R-008 */
  private screen(request: SettlementRequest, parameters: BusinessParameters): Screening {
    for (const rule of this.policies.eligibilityRules) {
      const reason = rule.evaluate(request, parameters);
      if (reason !== null) {
        return { reason, observations: Observations.empty() };
      }
    }
    return this.screenArrears(request, parameters);
  }

  /** @rule R-007 */
  private screenArrears(request: SettlementRequest, parameters: BusinessParameters): Screening {
    const assessment = this.policies.arrears.assess(request, parameters);
    if (assessment === 'IN_ARREARS') {
      return { reason: 'PRIMA_EN_MORA', observations: Observations.empty() };
    }
    const empty = Observations.empty();
    const observations = assessment === 'TOLERATED_VIP' ? empty.add('TOLERANCIA_MORA_VIP') : empty;
    return { reason: null, observations };
  }

  /**
   * Cálculo de importes y decisión final.
   * @rule R-009
   * @rule R-013
   * @rule R-014
   * @rule R-015
   * @rule R-016
   * @rule R-017
   * @rule R-018
   * @rule R-019
   * @rule R-020
   */
  private liquidate(
    request: SettlementRequest,
    parameters: BusinessParameters,
    initial: Observations,
  ): SettlementResult {
    const p = this.policies;
    const base = p.limitCap.apply(request, initial);
    const deductible = p.deductible.compute(request, parameters, base.amount, base.observations);
    const covered = p.coveredCalculator.calculate(base.amount, deductible.amount, request.coveragePct);
    if (p.lowDeductible.isSatisfiedBy(covered)) {
      return SettlementResult.rejected('BAJO_DEDUCIBLE', deductible.observations);
    }
    const penalized = p.penalty.apply(covered, request, parameters, deductible.observations);
    if (p.sumCap.isExhausted(request)) {
      return SettlementResult.rejected('SUMA_ASEGURADA_AGOTADA', penalized.observations);
    }
    const capped = p.sumCap.apply(penalized.amount, request, penalized.observations);
    const withholding = p.withholding.apply(capped.amount, request, parameters, capped.observations);
    const amounts = SettlementAmounts.of(
      base.amount,
      deductible.amount,
      capped.amount,
      withholding.amount,
    );
    const decision = p.approval.decide(request, parameters, amounts.net);
    return SettlementResult.decided(decision.status, decision.reason, amounts, withholding.observations);
  }
}

