/** Caso de uso: liquida un siniestro y audita el resultado. */
export class SettleClaimService implements SettleClaimUseCase {
  private readonly settlement: ClaimSettlementService;
  private readonly claimState: ClaimStateSpecification;
  private readonly transition: ClaimStateTransition;
  private readonly audit: SettlementAuditPort;

  constructor(
    settlement: ClaimSettlementService,
    claimState: ClaimStateSpecification,
    transition: ClaimStateTransition,
    audit: SettlementAuditPort,
  ) {
    this.settlement = settlement;
    this.claimState = claimState;
    this.transition = transition;
    this.audit = audit;
  }

  /**
   * @rule R-001
   * @rule R-024
   */
  execute(command: SettleClaimCommand): SettlementResult {
    const stateError = this.guardClaimState(command.request);
    if (stateError !== null) {
      return stateError;
    }
    const loaded = BusinessParameters.fromRaw(command.rawParameters);
    if (!loaded.ok) {
      return SettlementResult.failed('ORA-20010', `Parametro no definido: ${loaded.missing}`);
    }
    const result = this.settlement.settle(command.request, loaded.parameters);
    this.audit.record(this.toAuditEntry(command.request, result));
    return result;
  }

  /** @rule R-001 */
  private guardClaimState(request: SettlementRequest): SettlementResult | null {
    const status = request.claimStatus;
    if (status === null || this.claimState.isSettleable(status)) {
      return null;
    }
    const id = request.claimId ?? '';
    return SettlementResult.failed('ORA-20001', `El siniestro ${id} no esta en estado REGISTRADO (${status})`);
  }

  /** @rule R-021 */
  private toAuditEntry(request: SettlementRequest, result: SettlementResult): SettlementAuditEntry {
    return {
      claimId: request.claimId,
      status: result.status,
      reasonCode: result.reasonCode,
      newClaimState: this.transition.next(result.status),
      settlementDate: request.processDate.iso,
    };
  }
}

const ENTRY_PATTERN = /^\s*([A-Za-z0-9_]+)\s*[=:]\s*(.+?)\s*$/;

function addEntry(entries: Map<string, string>, chunk: string): void {
  const match = ENTRY_PATTERN.exec(chunk);
  if (match !== null) {
    entries.set(match[1].toUpperCase(), match[2]);
  }
}

/** Convierte 'CLAVE=VALOR;CLAVE2=VALOR2' (o JSON plano) en un mapa de parámetros crudos. */
export function parseParameters(text: string): Map<string, string> {
  const entries = new Map<string, string>();
  const cleaned = text.replace(/[{}"']/g, '');
  for (const chunk of cleaned.split(/[;,\n]/)) {
    addEntry(entries, chunk);
  }
  return entries;
}

import { Decimal } from '../../../domain/shared/decimal.ts';
import { toMoney, ZERO_MONEY } from '../../../domain/shared/rounding.ts';
import { CalendarDate } from '../../../domain/model/CalendarDate.ts';

const DECIMAL_PATTERN = /^-?\d+(\.\d+)?$/;
const INTEGER_PATTERN = /^\d+$/;
const TRUE_VALUES: readonly string[] = ['true', '1', 's', 'si', 'y', 'yes'];
const FALSE_VALUES: readonly string[] = ['false', '0', 'n', 'no'];

/** Lee y convierte campos de texto a tipos del dominio, recordando el primer campo inválido. */
export class FieldReader {
  private readonly input: Record<string, string>;
  private invalidField: string | null;

  constructor(input: Record<string, string>) {
    this.input = input;
    this.invalidField = null;
  }

  get firstInvalidField(): string | null {
    return this.invalidField;
  }

  private raw(name: string): string | null {
    const value = this.input[name];
    return typeof value === 'string' ? value.trim() : null;
  }

  private fail(name: string): void {
    if (this.invalidField === null) {
      this.invalidField = name;
    }
  }

  text(name: string): string {
    const value = this.raw(name);
    if (value === null || value === '') {
      this.fail(name);
      return '';
    }
    return value;
  }

  optionalText(name: string): string | null {
    const value = this.raw(name);
    return value === null || value === '' ? null : value;
  }

  money(name: string): Decimal {
    const value = this.raw(name);
    if (value === null || !DECIMAL_PATTERN.test(value)) {
      this.fail(name);
      return ZERO_MONEY;
    }
    return toMoney(Decimal.of(value));
  }

  integer(name: string): number {
    const value = this.raw(name);
    if (value === null || !INTEGER_PATTERN.test(value)) {
      this.fail(name);
      return 0;
    }
    return parseInt(value, 10);
  }

  date(name: string): CalendarDate {
    const value = this.raw(name);
    const parsed = value === null ? null : CalendarDate.parse(value);
    if (parsed === null) {
      this.fail(name);
      return CalendarDate.epoch();
    }
    return parsed;
  }

  flag(name: string): boolean {
    const value = (this.raw(name) ?? '').toLowerCase();
    if (TRUE_VALUES.includes(value)) {
      return true;
    }
    if (!FALSE_VALUES.includes(value)) {
      this.fail(name);
    }
    return false;
  }
}

import type { SettleClaimCommand } from '../../../application/ports/SettleClaimUseCase.ts';
