import { parseParameters } from './ParameterParser.ts';

export type InputMappingResult =
  | { readonly ok: true; readonly command: SettleClaimCommand }
  | { readonly ok: false; readonly field: string };

/** Adaptador de entrada: convierte Record<string,string> en un comando tipado. */
export class SettlementInputMapper {
  map(input: Record<string, string>): InputMappingResult {
    const reader = new FieldReader(input);
    const request = this.readRequest(reader);
    const rawParameters = parseParameters(reader.text('params'));
    if (reader.firstInvalidField !== null) {
      return { ok: false, field: reader.firstInvalidField };
    }
    return { ok: true, command: { request, rawParameters } };
  }

  private readRequest(reader: FieldReader): SettlementRequest {
    return {
      claimId: reader.optionalText('claim_id'),
      claimStatus: reader.optionalText('claim_status'),
      claimedAmount: reader.money('claimed_amount'),
      occurrenceDate: reader.date('occurrence_date'),
      reportDate: reader.date('report_date'),
      processDate: reader.date('process_date'),
      policyStatus: reader.text('policy_status'),
      policyStartDate: reader.date('policy_start_date'),
      policyEndDate: reader.date('policy_end_date'),
      lineOfBusiness: reader.text('line_of_business'),
      sumInsured: reader.money('sum_insured'),
      deductibleType: reader.text('deductible_type'),
      deductibleValue: reader.money('deductible_value'),
      pendingPremium: reader.money('pending_premium'),
      customerCategory: reader.text('customer_category'),
      coverageFound: reader.flag('coverage_found'),
      coverageLimit: reader.money('coverage_limit'),
      coveragePct: reader.money('coverage_pct'),
      waitingDays: reader.integer('waiting_days'),
      priorLiquidatedClaims365d: reader.integer('prior_liquidated_claims_365d'),
      totalIndemnified: reader.money('total_indemnified'),
    };
  }
}

import type { SettlementResult } from '../../../domain/model/SettlementResult.ts';

/** Serializa el resultado como cadenas; los importes con escala exacta 2. */
export function toOutputRecord(result: SettlementResult): Record<string, string> {
  const amounts = result.amounts;
  return {
    status: result.status,
    reason_code: result.reasonCode,
    base_amount: amounts.base.setScale(2, 'HALF_UP').toString(),
    deductible_amount: amounts.deductible.setScale(2, 'HALF_UP').toString(),
    covered_amount: amounts.covered.setScale(2, 'HALF_UP').toString(),
    withholding_amount: amounts.withholding.setScale(2, 'HALF_UP').toString(),
    net_amount: amounts.net.setScale(2, 'HALF_UP').toString(),
    observations: result.observations,
  };
}

import type { SettleClaimUseCase } from '../../../application/ports/SettleClaimUseCase.ts';
