import { toOutputRecord } from './SettlementOutputMapper.ts';

/** Adaptador de entrada: mapea la entrada, delega al caso de uso y serializa la salida. */
export class ClaimSettlementEndpoint {
  private readonly mapper: SettlementInputMapper;
  private readonly useCase: SettleClaimUseCase;

  constructor(mapper: SettlementInputMapper, useCase: SettleClaimUseCase) {
    this.mapper = mapper;
    this.useCase = useCase;
  }

  handle(input: Record<string, string>): Record<string, string> {
    const mapped = this.mapper.map(input);
    if (!mapped.ok) {
      return toOutputRecord(SettlementResult.failed('ENTRADA_INVALIDA', `Campo invalido: ${mapped.field}`));
    }
    return toOutputRecord(this.useCase.execute(mapped.command));
  }
}

import type {
  SettlementAuditEntry,
  SettlementAuditPort,
} from '../../../application/ports/SettlementAuditPort.ts';

/** Puerto de salida simulado: guarda las entradas de auditoría en memoria. */
export class InMemoryAuditLog implements SettlementAuditPort {
  private readonly records: SettlementAuditEntry[];

  constructor() {
    this.records = [];
  }

  record(entry: SettlementAuditEntry): void {
    this.records.push(entry);
  }

  entries(): readonly SettlementAuditEntry[] {
    return [...this.records];
  }
}

