function buildSettlementService(): ClaimSettlementService {
  return new ClaimSettlementService({
    eligibilityRules: [
      new PolicyInForceRule(),
      new OccurrenceWithinValidityRule(),
      new ReportingDeadlineRule(),
      new CoverageContractedRule(),
      new WaitingPeriodRule(),
    ],
    arrears: new PremiumArrearsPolicy(),
    limitCap: new CoverageLimitCap(),
    deductible: new DeductibleCalculator(
      new FixedDeductibleStrategy(),
      new PercentageDeductibleStrategy(),
      new VipDeductibleDiscount(),
    ),
    coveredCalculator: new CoveredAmountCalculator(),
    lowDeductible: new LowDeductibleSpecification(),
    penalty: new ClaimsFrequencyPenalty(),
    sumCap: new SumInsuredCap(),
    withholding: new WithholdingPolicy(),
    approval: new ApprovalDecisionPolicy(new FraudAlertSpecification()),
  });
}

function buildEndpoint(): ClaimSettlementEndpoint {
  const useCase = new SettleClaimService(
    buildSettlementService(),
    new ClaimStateSpecification(),
    new ClaimStateTransition(),
    new InMemoryAuditLog(),
  );
  return new ClaimSettlementEndpoint(new SettlementInputMapper(), useCase);
}

/** Punto de entrada: compone dependencias y delega; no contiene lógica de negocio. */
export function execute(input: Record<string, string>): Record<string, string> {
  return buildEndpoint().handle(input);
}

